// Frontend authentication service
// This will be implemented with Better Auth once the library is properly configured

export interface User {
  id: string;
  email: string;
  createdAt: string;
}

export interface AuthResponse {
  token: string;
  user: User;
  access_token: string;
  token_type: string;
}

class AuthService {
  private baseUrl: string = process.env.NEXT_PUBLIC_API_URL || 'http://localhost:8000';

  async register(email: string, password: string): Promise<AuthResponse> {
    const response = await fetch(`${this.baseUrl}/auth/register`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({ email, password }),
    });

    if (!response.ok) {
      const errorData = await response.json();
      console.error('Registration error response:', errorData);
      throw new Error(errorData.detail || 'Registration failed');
    }

    const data = await response.json();
    console.log('Registration response data:', data); // Debug log

    // Validate the response structure
    if (!data.access_token || !data.user) {
      throw new Error('Invalid response format from server');
    }

    // Map the response to match our expected format
    return {
      user: data.user,
      access_token: data.access_token,
      token_type: data.token_type
    };
  }

  async login(email: string, password: string): Promise<AuthResponse> {
    const response = await fetch(`${this.baseUrl}/auth/login`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({ email, password }),
    });

    if (!response.ok) {
      const errorData = await response.json();
      console.error('Login error response:', errorData);
      throw new Error(errorData.detail || 'Login failed');
    }

    const data = await response.json();
    console.log('Login response data:', data); // Debug log

    // Validate the response structure
    if (!data.access_token || !data.user) {
      throw new Error('Invalid response format from server');
    }

    // Map the response to match our expected format
    return {
      user: data.user,
      access_token: data.access_token,
      token_type: data.token_type
    };
  }

  async logout(): Promise<void> {
    // Clear local storage or any stored tokens
    localStorage.removeItem('token');
  }

  async getCurrentUser(): Promise<User | null> {
    const token = localStorage.getItem('token');
    if (!token) {
      return null;
    }

    try {
      const response = await fetch(`${this.baseUrl}/auth/me`, {
        method: 'GET',
        headers: {
          'Authorization': `Bearer ${token}`,
          'Content-Type': 'application/json',
        },
      });

      if (!response.ok) {
        // If the response is not ok, check the status and return null
        if (response.status === 401 || response.status === 403) {
          // Token is invalid/expired, clear it
          this.logout();
        }
        return null;
      }

      const userData = await response.json();
      // Ensure the response format matches our User interface
      return {
        id: userData.id,
        email: userData.email,
        created_at: userData.created_at || userData.createdAt,
        updated_at: userData.updated_at || userData.updatedAt
      };
    } catch (error) {
      console.error('Error fetching user:', error);
      // If there's an error, clear the token to prevent repeated failed attempts
      this.logout();
      return null;
    }
  }

  setToken(token: string): void {
    console.log('Setting token in localStorage:', token); // Debug log
    localStorage.setItem('token', token);
  }

  getToken(): string | null {
    const token = localStorage.getItem('token');
    console.log('Getting token from localStorage:', token); // Debug log
    return token;
  }

  isAuthenticated(): boolean {
    return !!this.getToken();
  }
}

export const authService = new AuthService();